var MyWorkspace = {
    init: async function (app, container) {

        $("div[name=splitter]", container).kendoSplitter({
			scrollable: false,
            height: "100%",
			panes: [
				{ collapsible: false, scrollable: false, size: "350px" },
				{ collapsible: false, scrollable: false }
			]
		});

        $("button[name=newConnection]", container).on("click", async function() { 
            await MyWorkspace.connect(app, container); 
        });

        await MyWorkspace.connect(app, container);
    },

    connect: async function(app, container) {
        var connectionInfoDialog = new Dialog({ width: 420, title: "[resource_displayname[newconnection]]" });
        connectionInfoDialog.template = $("script[name=newConnectionDialog]").first().html();

        var environments = MyWorkspace.getEnvironments(app);
        var types = MyWorkspace.getTypes();
        var sources = MyWorkspace.getSources();
        var environmentApi = new Api();

        environments.change = async function() {
            environmentApi.apiRoot = $("[name=environment]", connectionInfoDialog.element).val();
            var sources = await MyWorkspace.getSources(environmentApi);
            $("[name=source]", connectionInfoDialog.element).kendoDropDownList(sources);
        };

        connectionInfoDialog.events.connect = async function() {
            var connectionInfo = {
                api: environmentApi,
                environment: $("[name=environment]", connectionInfoDialog.element).val(),
                type: $("[name=type]", connectionInfoDialog.element).val(),
                app: await environmentApi.get("ContentManagement/App(" + $("[name=source]", connectionInfoDialog.element).val() + ")")
            };

            await MyWorkspace.addConnection(connectionInfo, app, $("[name=connections]", container));
            connectionInfoDialog.events.close();
        };

        connectionInfoDialog.init(async () => {
            $("[name=environment]", connectionInfoDialog.element).kendoDropDownList(environments);
            $("[name=type]", connectionInfoDialog.element).kendoDropDownList(types);
            await environments.change();
        });
    },

    addConnection: async function(connectionInfo, app, container) {

        var connectionComponent = 
            await loadComponent(container, connectionInfo.type);
        
        await connectionComponent.init(
            app, 
            $(".component[name=" + connectionInfo.type + "]"), 
            connectionInfo);
    },

    getEnvironments: function(app) {
        var environments = JSON.parse(JSON.stringify(app.Config.Deployment.Targets));

        environments.push({
            "Api": "https://" + app.Domain + "/Api/",
            "Domain": app.Domain,
            "Name": "Currently Hosting (this one)"
        });

        return { index: 0, dataTextField: "Name", dataValueField: "Api", dataSource: environments };
    },
    

    getTypes: function() {
        var connectionTypes = [ 
            { Name: "Content Management", Value: "CMS" },
            { Name: "Document Management", Value: "DMS" } 
        ];

        return { dataTextField: "Name", dataValueField: "Value", dataSource: connectionTypes };
    },

    getSources: async function(api) {
        var sources = api != null 
            ? await api.get("ContentManagement/App")
            : [];
            
        return { dataTextField: "Name", dataValueField: "Id", dataSource: sources.value };
    }
}
